def transform(grid):
    # Extend the terminal contiguous run of foreground color to the right edge
    # only when that run has at least three cells.
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        c = len(row) - 1
        while c >= 0 and row[c] == bg:
            c -= 1
        if c < 0:
            continue
        color = row[c]
        start = c
        while start >= 0 and row[start] == color:
            start -= 1
        if c - start >= 3:
            for k in range(c + 1, len(row)):
                out[r][k] = 1
    return out

